SELECT
    category AS category,
    category_source AS categorySource,
    category_confidence AS categoryConfidence,
    classifier_version AS classifierVersion
FROM TRANSACTIONS
WHERE user_id = #{userId}
  AND source_type = #{sourceType}
  AND source_organization_code = #{sourceOrganizationCode}
  AND source_dedup_key = #{sourceDedupKey}
LIMIT 1

SELECT transaction_id
FROM TRANSACTIONS
WHERE user_id = #{userId}
  AND source_type = #{sourceType}
  AND source_organization_code = #{sourceOrganizationCode}
  AND source_dedup_key = #{sourceDedupKey}
LIMIT 1
